import { useEffect, useRef, useState } from "react";
import { Routes, Route, useLocation, useSearchParams } from "react-router-dom";

import Header from "./components/header/header";
import Loader from "./components/loader/loader";

import Home from "./pages/home/home";
import NotFound from "./pages/notFound/notFound";
import Cases from "./pages/archiveCases/archiveCases";
import SingleCase from "./pages/singleCase/singleCase";
import About from "./pages/about/about";
import Contacts from "./pages/contacts/contacts";

function App() {
  const mainElem = useRef(null);
  const { pathname } = useLocation();
  const [showLoader, setShowLoader] = useState(false);
  const [oldPathname, setOldPathname] = useState(pathname);

  useEffect(() => {
    if (oldPathname !== pathname) {
      setShowLoader(true);
      setTimeout(() => {
        setOldPathname(pathname);
        setShowLoader(false);
        mainElem.current?.scrollTo(0, 0);
      }, 600);
    }
  }, [mainElem, pathname, oldPathname]);


  const [siteData, setSiteData] = useState({});
  useEffect(() => {
    fetch("/data.json")
      .then(data => data.json())
      .then(result => {
        setSiteData(result);
      });
  }, [setSiteData]);

  const [widthScreen, setWidthScreen] = useState(
    () => typeof window !== 'undefined' && window.innerWidth <= 580
  );

  useEffect(() => {
    const handleResize = () => {
      setWidthScreen(window.innerWidth <= 580);
    };

    handleResize(); // синхронизация на случай SSR/первого рендера
    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const [searchParams] = useSearchParams();

  return (
    <>
      <head>
        {widthScreen ?
          <meta name="viewport" content="width=490, user-scalable=no" />
          :
          <meta name="viewport" content="width=device-width, initial-scale=1" />
        }


      </head>
      <Loader show={showLoader} />
      <Header />
      <main ref={mainElem}>
        <Routes location={oldPathname + (searchParams ? "?" + searchParams.toString() : "")}>
          <Route path="/" element={<Home data={siteData ? siteData : {}} />}></Route>
          <Route path="/cases/" element={<Cases data={siteData ? siteData : {}} />} />
          <Route path="/cases/page/:currentPage/" element={<Cases data={siteData ? siteData : {}} />} />
          <Route path="/cases/:title/" element={<SingleCase />} />
          <Route path="/about/" element={<About data={siteData ? siteData : {}} />} />
          <Route path="/contacts/" element={<Contacts data={siteData ? siteData : {}} />} />
          <Route path="*" element={<NotFound></NotFound>}></Route>
        </Routes>
      </main>
    </>
  );
}

export default App;
