import { Link } from "react-router-dom";
import "./breadcrumbs.css";
export default function Breadcrumbs({children}) {
    return (
        <>
            <section className="beadcrumbs">
                <ul>
                    <li><Link to="/">Главная</Link></li>
                    {children}
                </ul>
            </section>
        </>
    )
}