import { NavLink } from "react-router-dom";
import "./sectionTop.css";

export default function SectionTop({ suptitle = false, title = false, btn = false }) {
    return (
        <>
            <div className="section__top">
                <div className="section__top_title">
                    {suptitle && <p>{suptitle}</p>}
                    {title && <h2>{title}</h2>}
                </div>
                {btn && <NavLink to={btn._url} className="action__btn">{btn?._label}</NavLink>}
            </div>
        </>
    )
}