import { Link } from "react-router-dom";
import placeholder from "./../../assets/img/placeholder.jpg";

import "./articleCase.css";

export function SkeletonArticleCase() {
    return (
        <>
            <article className="article--case skeleton">
                <div className="article--case__thumb">
                    &nbsp;
                </div>
                <div className="article--case__data">
                    <p className="article--case__type">&nbsp;</p>
                    <h3 className="article--case__name">&nbsp;</h3>
                    <span>Подробнее</span>
                </div>
            </article>
        </>
    )
}

export default function ArticleCase(data) {
    const type = [
        { title: "landing", label: "Лендинг" },
        { title: "web-shop", label: "Интернет-магазин" },
        { title: "corp", label: "Корпоративный" },
        { title: "react", label: "React" },
    ];
    return (
        <>
            <article className="article--case">
                <div className="article--case__thumb">
                    <img src={data.img ? data.img : placeholder} width={466} height={230} alt="alt" />
                </div>
                <div className="article--case__data">
                    <p className="article--case__type">{type[data.type].label}</p>
                    <h3 className="article--case__name">{data.name}</h3>
                    <Link to={`/cases/${data.title}/`}>Подробнее</Link>
                </div>
            </article>
        </>
    )
}