import { Link } from "react-router-dom";

import Breadcrumbs from "../../components/breadcrumbs/breadcrumbs";
import PagePoster from "../../components/pagePoster/pagePoster";
import SectionTop from "../../components/sectionTop/sectionTop";
import CtaBlock from "./../../components/ctaBlock/ctaBlock";
import StagesDev from "../../components/stagesDev/stagesDev";

import placeholder from "./../../assets/img/placeholder.jpg";
import "./about.css";


export default function About({ data }) {
    return (
        <>
            <Breadcrumbs>
                <li><Link to="/about/">Обо мне</Link></li>
            </Breadcrumbs>
            <PagePoster
                title="Обо мне"
                desc="Кто я и чем могу быть полезен"
                btn={{
                    _url: "https://t.me/smiriix/",
                    _label: "Написать мне"
                }}
            />
            {data?.about &&
                <>
                    <section className="section--white">
                        <div className="container">
                            <SectionTop
                                suptitle="Обо мне"
                                title="Кто я такой"
                            />
                            <div className="about__grid">
                                {data.about.text && <div className="about__text" dangerouslySetInnerHTML={{ __html: data.about.text }} />}
                                <div className="about__img">
                                    <img src={(data?.about.photo && data.about.photo) ? data.about.photo : placeholder} width={403} height={598} alt="Vladislav N." />
                                </div>
                            </div>
                        </div>
                    </section>
                    {data.about?.roadmap &&
                        <section>
                            <div className="container">
                                <div className="roadmap__grid">
                                    <div className="roadmap__left">
                                        <SectionTop
                                            suptitle="Опыт работы"
                                            title="Мой путь веб-разработчика"
                                        />
                                    </div>
                                    <div className="roadmap__list">
                                        {data.about.roadmap.map((item, index) => {
                                            return <div key={index} className="roadmap__item">
                                                <h3>{item.year}</h3>
                                                <p dangerouslySetInnerHTML={{ __html: item.desc }} />
                                                <span>{item.post}</span>
                                            </div>
                                        })}
                                    </div>
                                </div>
                            </div>
                        </section>
                    }
                    {data.about?.stack &&
                        <section>
                            <div className="container">
                                <SectionTop
                                    suptitle="Мой стек технологий"
                                    title="С чем работаю каждый день"
                                />
                                <div className="stack__list">
                                    {data.about.stack.map((item, index) => {
                                        return <div key={index} className="stack__row">
                                            <h3>{item.label}</h3>
                                            <div className="stack__row_list">
                                                {item?.list && item.list.map((subitem, subindex)=>{
                                                    return <span key={index + "_" + subindex}>{subitem}</span>
                                                })}
                                            </div>
                                        </div>
                                    })}

                                </div>
                            </div>
                        </section>
                    }
                </>
            }
            {data?.stages && <StagesDev list={data.stages} />}
            <CtaBlock />
        </>
    )
}