import "./stagesDev.css";
import SectionTop from "../sectionTop/sectionTop";
import { Link } from "react-router-dom";

export default function StagesDev({list = {}}) {;
    return (
        <>
            {list &&
                <section className="stages--dev">
                    <div className="container">
                        <SectionTop
                            suptitle="Этапы разработки"
                            title="Как строится процесс разработки"
                        />
                        <div className="stages--dev__grid">
                            {list.map((item, index) => {
                                return <div key={index} className="stages--dev__item">
                                    <span>{(index + 1).toString().padStart(2, 0)}</span>
                                    <h3>{item.label}</h3>
                                    <p>{item.desc}</p>
                                </div>
                            })
                            }
                            <div className="stages--dev__item">
                                <span>{(list.length + 1).toString().padStart(2, 0)}</span>
                                <h3>Написать мне</h3>
                                <p>Обсудим ваш проект</p>
                                <Link to="https://t.me/smiriix" target="_blank" className="action__btn">Написать мне</Link>
                            </div>
                        </div>
                    </div>
                </section>
            }
        </>
    )
}