import { Link } from "react-router-dom";

import "./ctaBlock.css";

import ctaImg from "./../../assets/img/cta--block.jpg";
import SectionTop from "../sectionTop/sectionTop";

export default function CtaBlock() {
    return (
        <>
            <section className="section--white cta--block">
                <div className="container">
                    <div className="cta--block__grid">
                        <div className="cta--block__img">
                            <img src={ctaImg} width={708} height={432} alt="Остались вопросы?" />
                        </div>
                        <div className="cta--block__info">
                            <SectionTop
                                suptitle="Остались вопросы?"
                                title="Напишите — отвечу лично и помогу разобраться"
                            />
                            <p>Вёрстка сайтов на WordPress, OpenCart и Bitrix, адаптив под мобильные, посадка на CMS и перенос на сервер.</p>
                            <Link to="https://t.me/smiriix" target="_blank" className="action__btn">Написать мне</Link>
                        </div>
                    </div>
                </div>
            </section>
        </>
    )
}