import { Link } from "react-router-dom";

import "./notFound.css";

import img from "./../../assets/img/main--poster.jpg";

export default function NotFound() {
    return (
        <>
            <section className="not--found">
                <div className="not--found__img">
                    <img src={img} width={1920} height={1080} alt="Страница не найдена" />
                </div>
                <div className="container">
                    <div className="not--found__data">
                        <h1>404</h1>
                        <p>Кажется, вы свернули не туда</p>
                        <span>Возможно, страница была удалена, переехала или в адресе опечатка.</span>
                        <Link to="/" className="action__btn">На главную</Link>
                    </div>
                </div>
            </section>
        </>
    )
}