import { useState } from "react";

import SectionTop from "./../sectionTop/sectionTop";

import "./faq.css";

function FaqItem({ label = null, desc = null }) {
    const [showFaq, setShowFaq] = useState(false);
    return (
        <>
            <div className={"faq__item" + (showFaq ? " show" : "")}>
                <h3 onClick={()=>{setShowFaq(!showFaq)}}>{label}</h3>
                <div className="faq__item_text--wrapper">
                    <div className="faq__item_text">
                        <p>{desc}</p>
                    </div>
                </div>
            </div>
        </>
    )
}

export default function Faq({ list = {} }) {
    return (
        <>
            <section className="section--white faq">
                <div className="container">
                    <SectionTop
                        suptitle="Часто задаваемые вопросы"
                        title="Ответы, которые сэкономят ваше время"
                    />
                    <div className="faq__list">
                        {list &&
                            list.map((item, index) => {
                                return <FaqItem key={index} {...item} />
                            })
                        }
                    </div>
                </div>
            </section>
        </>
    )
}