import { Link, NavLink } from "react-router-dom";


import SectionTop from "../../components/sectionTop/sectionTop";
import CasesSlider from "../../components/casesSlider/casesSlider";

import "./home.css";

import posterImg from "./../../assets/img/main--poster.jpg"
import logo from "./../../assets/img/logo.png";
import placeholder from "../../assets/img/placeholder.jpg";
import StagesDev from "../../components/stagesDev/stagesDev";
import Faq from "../../components/faq/faq";
import CtaBlock from "../../components/ctaBlock/ctaBlock";

export default function Home({ data = [] }) {
    return (
        <>
            <section className="home--poster">
                <div className="home--poster__image">
                    <img src={posterImg} width={1920} height={1080} alt="Vladislav N" />
                </div>
                <div className="home--poster__data">
                    <img src={logo} width={177} height={177} alt="Logo" />
                    <h1>Vladislav N.</h1>
                    <p>Веб-разработчик, который превращает ваш дизайн в функциональный сайт с базовой SEO оптимизацией.</p>
                    <div className="home--poster__btns">
                        <NavLink to="/cases/" className={"action__btn"}>Смотреть кейсы</NavLink>
                    </div>
                </div>
            </section>
            {data?.stats &&
                <section className="section--white stats">
                    <div className="container">
                        <SectionTop
                            suptitle="Статистика"
                            title="Немного о моих достижениях в цифрах"
                        />
                        <div className="stats__grid">
                            {data.stats.map((stat, index) => {
                                return <div key={index} className="stats__item">
                                    <h3>
                                        {stat.number}
                                        <span>{stat.label}</span>
                                    </h3>
                                    <p>{stat.desc}</p>
                                </div>
                            })
                            }

                        </div>
                    </div>
                </section>
            }
            {
                data?.about_me &&
                <section className="section--white about--me">
                    <div className="container">
                        <SectionTop
                            suptitle="Обо мне"
                            title="Кто я и чем могу быть полезен"
                        />
                        <div className="about--me__grid">
                            <div className="about--me__left">
                                {data.about_me.title && <p className="about--me__welcome">{data.about_me.title}</p>}
                                {data.about_me.desc && <p>
                                    {data.about_me.desc}
                                </p>}
                                <div className="about--me__adventages">
                                    {data.about_me.adventages.map((item, index) => {
                                        return <div key={index} className="about--me__adventage">
                                            <div className="about--me__adventage_data">
                                                <p>{item.label}</p>
                                                <span>{item.desc}</span>
                                            </div>
                                        </div>
                                    })}
                                </div>
                                <div className="about--me__btns">
                                    <Link to="/about/" className="action__btn">Подробнее</Link>
                                    <Link to="https://t.me/smiriix" target="_blank" className="action__btn">Написать мне</Link>
                                </div>
                            </div>
                            <div className="about--me__right">
                                <div className="about--me__photo">
                                    <img src={data.about_me.photo ? data.about_me.photo : placeholder} width={417} height={498} alt="Vladislav N." />
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
            }
            <CasesSlider />
            {data?.stages && <StagesDev list={data.stages} />}
            {data?.faq && <Faq list={data.faq} />}
            <CtaBlock />
        </>
    )
}