import { useEffect, useState } from "react";
import { NavLink, Link, useParams, useSearchParams } from "react-router-dom";

import ArticleCase, { SkeletonArticleCase } from "../../components/articleCase/articleCase";
import CtaBlock from "./../../components/ctaBlock/ctaBlock";

import Breadcrumbs from "../../components/breadcrumbs/breadcrumbs";
import PagePoster from "../../components/pagePoster/pagePoster";

import "./archiveCases.css";
const countOnPage = 12,
    type = [
        { title: "landing", label: "Лендинг" },
        { title: "web-shop", label: "Интернет-магазин" },
        { title: "corp", label: "Корпоративный" },
        { title: "react", label: "React" },
    ];
export default function Cases() {
    const [casesList, setCasesList] = useState([]),
        [loading, setLoading] = useState(true),
        [searchParams] = useSearchParams(),
        currentCategory = searchParams.get("category") ?? "",
        currentPage = useParams()?.currentPage ?? 1;


    useEffect(() => {
        setLoading(true);
        setCasesList([]);
        fetch("/cases.json")
            .then(data => data.json())
            .then(result => {
                if (currentCategory) {
                    let categoryIndex = type.findIndex(category => { return category.title === currentCategory });
                    result = result.filter(item => { return item.type === categoryIndex });
                }
                let newArr = [];
                result.reverse();
                for (let i = 0; i < result.length; i = i + countOnPage) {
                    newArr.push(result.slice(i, i + countOnPage));
                }
                setCasesList(newArr);
                setLoading(false);
            })
    }, [currentCategory, setCasesList]);
    return (
        <>
            <Breadcrumbs>
                <li><Link to="/cases/">Кейсы</Link></li>
            </Breadcrumbs>
            <PagePoster
                title="Кейсы"
                desc="Проекты, которые уже приносят результат"
            />
            <section className="archive--cases">
                <div className="container">
                    <div className="archive--cases__wrapper">
                        <ul className="archive--cases__filter">
                            <li>
                                <Link className={!currentCategory ? "active" : ""} to={`/cases/`}>
                                    Все
                                </Link>
                            </li>
                            {type.map((item, index) => {
                                return <li key={index}>
                                    <Link className={currentCategory === item.title ? "active" : ""} to={`/cases/?category=${item.title}`}>
                                        {item.label}
                                    </Link>
                                </li>
                            })}
                        </ul>
                        <div className="archive--cases__grid">
                            {loading && [...new Array(6)].map((_, index) => {
                                return <SkeletonArticleCase />
                            })}
                            {
                                (casesList.length && casesList[currentPage - 1]) ? casesList[currentPage - 1].map((item) => {
                                    return <ArticleCase key={item.id} {...item} />
                                })
                                    : !loading && <p>Проектов еще нет :)</p>
                            }
                        </div>
                        {casesList.length > 1 &&
                            <div className="pagination">
                                {currentPage > 1 &&
                                    <>
                                        {
                                            currentPage - 1 !== 1 ?
                                                <NavLink to={`/cases/page/${currentPage - 1}/${currentCategory ? "?category=" + currentCategory : ""}`} end>←</NavLink>
                                                : <NavLink to={`/cases/${currentCategory ? "?category=" + currentCategory : ""}`} end>←</NavLink>
                                        }
                                    </>
                                }
                                <NavLink to={`/cases/${currentCategory ? "?category=" + currentCategory : ""}`} end>1</NavLink>
                                {[...new Array(casesList.length)].map((_, index) => {
                                    if (index + 1 > 1)
                                        return <NavLink key={index + 1} to={`/cases/page/${(index + 1)}/${currentCategory ? "?category=" + currentCategory : ""}`}>{index + 1}</NavLink>
                                    return null
                                })
                                }
                                {currentPage < casesList.length && <NavLink to={`/cases/page/${+currentPage + 1}/${currentCategory ? "?category=" + currentCategory : ""}`} end>→</NavLink>}

                            </div>
                        }
                    </div>
                </div>
            </section>
            <CtaBlock />
        </>
    )
}