import { Link } from "react-router-dom";

import "./pagePoster.css";
import posterImg from "./../../assets/img/main--poster.jpg";

export default function PagePoster(data = {}) {
    return (
        <>
            <section className="page--poster">
                <div className="page--poster__img">
                    <img src={data?.img ? data?.img : posterImg} width={1920} height={540} alt={data?.title} style={data?.style} />
                </div>
                <div className="container">
                    <div className="page--poster__data">
                        <h1>{data?.title}</h1>
                        <p>{data?.desc}</p>
                        <div className="page--poster__btns">
                            {data?.btn && <Link to={data?.btn._url} target="_blank" className="action__btn">{data?.btn._label}</Link>}
                        </div>
                    </div>
                </div>
            </section>
        </>
    )
}