import { useEffect, useState } from "react";
import { Link, NavLink, useLocation } from "react-router-dom";

import './header.css';

import logo from "./../../assets/img/logo.png";
import youtube from "../../assets/img/youtube.svg";
import vk from "../../assets/img/vk.svg";
import github from "../../assets/img/github.svg";
import telegram from "../../assets/img/telegram.svg";


export default function Header() {
    const [menuActive, setMenuActive] = useState(false);
    const { pathname } = useLocation();
    useEffect(() => {
        setMenuActive(false);
    }, [pathname]);
    return (
        <>
            <header className="header">
                <div className="header__wrapper">
                    <Link to="/" className="header__logo">
                        <img src={logo} width={57} height={57} alt="Logo" />
                    </Link>
                    <div className={`header__btn${menuActive ? ' active' : ""}`} onClick={() => setMenuActive(!menuActive)}>
                        <span>
                            <span></span>
                            <span></span>
                            <span></span>
                        </span>
                        Меню
                    </div>
                    <div className="header__socials">
                        <a href="https://youtube.com/@VladNoskov19" target="_blank" rel="noreferrer" style={{ "--icon": `url(${youtube})` }}>YouTube</a>
                        <a href="https://vk.me/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${vk})` }}>Вконтакте</a>
                        <a href="https://github.com/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${github})` }}>GitHub</a>
                        <a href="https://t.me/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${telegram})` }}>Telegram</a>
                    </div>
                </div>
            </header>
            <div className={`header__overlay${menuActive ? ' active' : ""}`}>
                <div className="header__menu">
                    <NavLink to="/">Главная</NavLink>
                    <NavLink to="/cases/">Кейсы</NavLink>
                    {/* <NavLink to="/pets/">Pet-Проекты</NavLink> */}
                    <NavLink to="/about/">Обо мне</NavLink>
                    <NavLink to="/contacts/">Контакты</NavLink>
                </div>
            </div>
        </>
    );
}