import { useEffect, useRef, useState } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation } from "swiper/modules";
import 'swiper/css';
import 'swiper/css/navigation';


import SectionTop from "../sectionTop/sectionTop";

import "./casesSlider.css";
import ArticleCase, { SkeletonArticleCase } from "../articleCase/articleCase";

export default function CasesSlider({ title = null, suptitle = null, list = null }) {
    const [casesList, setCasesList] = useState([]);
    const [swiper, setSwiper] = useState(null);
    const [loadAritcles, setLoadArticles] = useState(false);
    const arrowPrev = useRef(null);
    const arrowNext = useRef(null);

    useEffect(() => {
        if (list && list.length) {
            setCasesList(list);
        } else {
            fetch("/cases.json")
                .then(data => data.json())
                .then(result => {
                    setCasesList(result);
                    setLoadArticles(true);
                })
        }
    }, [list]);

    useEffect(() => {
        if (!swiper || !arrowNext.current || !arrowPrev.current)
            return;


        swiper.params.navigation.prevEl = arrowPrev.current;
        swiper.params.navigation.nextEl = arrowNext.current;
        swiper.navigation.destroy();
        swiper.navigation.init();
        swiper.navigation.update();
    }, [swiper]);
    return (
        <>
            <section className="slider--cases">
                <div className="container">
                    <SectionTop
                        suptitle={suptitle ? suptitle : "Кейсы"}
                        title={title ? title : "Последние проекты"}
                        btn={{ _label: "Смотреть кейсы", _url: "/cases/" }}
                    />
                    <div className="slider--cases__slider">
                        <Swiper
                            modules={[Navigation]}
                            spaceBetween={20}
                            slidesPerView={1}
                            onSwiper={setSwiper}
                            breakpoints={{
                                768: {
                                    slidesPerView: 2
                                },
                                1200: {
                                    spaceBetween: 20,
                                    slidesPerView: 3
                                },
                                1401: {
                                    spaceBetween: 50,
                                    slidesPerView: 3
                                }
                            }}
                        >
                            {!loadAritcles && [...new Array(6)].map((item, index) => {
                                return <SwiperSlide key={index}><SkeletonArticleCase /></SwiperSlide>
                            })}

                            {loadAritcles && casesList && casesList.slice(-6).reverse().map((item, index) => {
                                return <SwiperSlide key={item.id}>
                                    <ArticleCase {...item} />
                                </SwiperSlide>
                            })}

                        </Swiper>
                        <button ref={arrowPrev} className="slider--cases__slider_arrow prev"></button>
                        <button ref={arrowNext} className="slider--cases__slider_arrow next"></button>
                    </div>
                </div>
            </section>
        </>
    )
}