import { Link } from "react-router-dom";

import Breadcrumbs from "../../components/breadcrumbs/breadcrumbs";
import PagePoster from "../../components/pagePoster/pagePoster";
import SectionTop from "../../components/sectionTop/sectionTop";
import CtaBlock from "./../../components/ctaBlock/ctaBlock";
import StagesDev from "../../components/stagesDev/stagesDev";
import Faq from "../../components/faq/faq";

import placeholder from "./../../assets/img/placeholder.jpg";

import youtube from "../../assets/img/youtube.svg";
import vk from "../../assets/img/vk.svg";
import github from "../../assets/img/github.svg";
import telegram from "../../assets/img/telegram.svg";

import "./contacts.css";

export default function Contacts({ data }) {
    return <>
        <Breadcrumbs>
            <li><Link to="/contacts/">Контакты</Link></li>
        </Breadcrumbs>
        <PagePoster
            title="Контакты"
            desc="Открыт к проектам и сотрудничеству."
        />
        {data.contacts &&
            <section>
                <div className="container">
                    <div className="contacts__grid">
                        <div className="contacts__left">
                            <SectionTop
                                suptitle="Контакты"
                                title="Как со мной связаться"
                            />
                            <div className="contacts__text">
                                <div style={{display: "contents"}} dangerouslySetInnerHTML={{ __html: data.contacts.desc }}></div>
                                <div className="contacts__socials">
                                    <a href="https://youtube.com/@VladNoskov19" target="_blank" rel="noreferrer" style={{ "--icon": `url(${youtube})` }}>YouTube</a>
                                    <a href="https://vk.me/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${vk})` }}>Вконтакте</a>
                                    <a href="https://github.com/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${github})` }}>GitHub</a>
                                    <a href="https://t.me/smiriix" target="_blank" rel="noreferrer" style={{ "--icon": `url(${telegram})` }}>Telegram</a>
                                </div>
                            </div>
                        </div>
                        <div className="contacts__photo">
                            <img src={data.contacts?.photo && data.contacts.photo ? data.contacts.photo : placeholder} width={500} height={500} alt="Vladislav N." />
                        </div>
                    </div>
                </div>
            </section>
        }
        {data?.stages && <StagesDev list={data.stages} />}
        {data?.faq && <Faq list={data.faq} />}
        <CtaBlock />
    </>
}