import { useEffect, useState } from "react";
import { NavLink, useLocation, useParams } from "react-router-dom";
import { Fancybox } from "@fancyapps/ui/dist/fancybox/";
import "@fancyapps/ui/dist/fancybox/fancybox.css";

import Breadcrumbs from "../../components/breadcrumbs/breadcrumbs";
import PagePoster from "../../components/pagePoster/pagePoster";
import CasesSlider from "../../components/casesSlider/casesSlider";
import SectionTop from "../../components/sectionTop/sectionTop";
import CtaBlock from "../../components/ctaBlock/ctaBlock";

import "./singleCase.css";

Fancybox.bind("[data-fancybox]", {
});

export default function SingleCase() {
    const title = useParams()?.title || null,
        currentPage = useLocation().pathname,
        [currentCase, setCurrentCase] = useState(null),
        [casesList, setCasesList] = useState([]),
        [rndList, setRndList] = useState([]);

    let i = 0;

    useEffect(() => {
        fetch("/cases.json")
            .then(data => data.json())
            .then(result => {
                const findElem = result.find(item => { return item.title === title });
                setCurrentCase(findElem);
                setCasesList(result);
            })
    }, [title, setCurrentCase, setCasesList]);

    useEffect(() => {
        let newArr = [],
            maxCount = Math.min(6, casesList.length),
            pool = [...casesList];

        for (let i = 0; i < maxCount; i++) {
            const idx = Math.floor(Math.random() * pool.length);
            newArr.push(pool[idx]);
            pool.splice(idx, 1);
        }
        setRndList(newArr);
    }, [setRndList, casesList]);

    if (!currentCase)
        return null;

    return (
        <>
            <Breadcrumbs>
                <li><NavLink to="/cases/">Кейсы</NavLink></li>
                <li><NavLink to={`${currentPage}/`}>{currentCase.name}</NavLink></li>
            </Breadcrumbs>
            <PagePoster
                title={currentCase.name}
                desc={currentCase?.subtitle}
                btn={currentCase?.url && {
                    _url: currentCase?.url,
                    _label: "Смотреть сайт"
                }}
                style={{ objectPosition: "center top" }}
                img={currentCase?.banner ? currentCase.banner : null}
            />
            {currentCase?.about &&
                <section className="section--white">
                    <div className="container">
                        <SectionTop
                            suptitle="О проекте"
                            title="Кратко о клиенте и задаче"
                        />
                        <div className="section--desc" dangerouslySetInnerHTML={{ __html: currentCase?.about }} />
                    </div>
                </section>
            }
            {currentCase?.solutions &&
                <section className="section--white">
                    <div className="container">
                        <SectionTop
                            suptitle="Решение"
                            title="Что было сделано"
                        />
                        <div className="solitions__grid">
                            {currentCase?.solutions && currentCase.solutions.map((item, index) => {
                                return <div className="solitions__item" key={index}>
                                    <span>{(index + 1).toString().padStart(2, 0)}</span>
                                    <h3>{item.label}</h3>
                                    <p>{item.text}</p>
                                </div>
                            })}
                        </div>
                    </div>
                </section>
            }
            {currentCase?.result &&
                <section className="section--white">
                    <div className="container">
                        <SectionTop
                            suptitle="Результат"
                            title="Что получилось в итоге"
                        />
                        <div className="section--desc" dangerouslySetInnerHTML={{ __html: currentCase.result }} />
                    </div>
                </section>
            }
            {currentCase?.gallery &&
                <section>
                    <div className="container">
                        <SectionTop
                            suptitle="Галерея"
                            title="Внутренние страницы"
                        />
                        <div className="gallery__grid">
                            {currentCase.gallery.map((item, index) => {
                                if (i === 7) {
                                    i = 0;
                                }
                                i++;
                                return <a key={index} href={item} data-fancybox={"gallery"} className={"gallery__item gallery__item_" + i}>
                                    <img src={item} width={464} height={542} alt="" />
                                </a>;
                            })}
                        </div>
                    </div>
                </section>
            }
            <CasesSlider
                suptitle="Кейсы"
                title="Другие проекты"
                list={rndList}
            />
            <CtaBlock />
        </>
    )
}